<?php declare(strict_types=1); require_once dirname(__DIR__).'/_bootstrap.php';apiMethod('DELETE','POST');apiCsrf();$uid=apiAuth(['supplier','manufacturer','admin']);$in=apiInput();$id=apiId($in['id']??$_GET['id']??0);$db=apiDb();$s=$db->prepare('SELECT p.id FROM products p LEFT JOIN suppliers s ON s.id=p.supplier_id WHERE p.id=? AND (s.user_id=? OR ?="admin")');$s->execute([$id,$uid,currentRole()]);if(!$s->fetch())apiError('Not found',404);$db->prepare("UPDATE products SET status='inactive' WHERE id=?")->execute([$id]);apiResponse(['id'=>$id]);